import {webkit} from 'playwright';
const browser=await webkit.launch({headless:true}),page=await browser.newPage({userAgent:'Mozilla/5.0 (iPhone; CPU iPhone OS 18_6 like Mac OS X) AppleWebKit/605.1.15 (KHTML, like Gecko) Version/18.6 Mobile/15E148 Safari/604.1',viewport:{width:390,height:844}});const pageErrors=[];page.on('pageerror',e=>pageErrors.push(String(e.message||e)));
